import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, color, mix, smoothstep, step, clamp, float, max, positionLocal, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, Shape, ExtrudeGeometry, PlaneGeometry, DirectionalLight } = ctx.THREE;

  const root = new Group();
  root.name = 'gradient-cta-object';

  const disposables = [];
  const primitiveHandles = [];
  const timelines = [];

  // ---------------------------------------------------------------
  // STAGE — engineered dark gradient backdrop (surface -> background)
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const bgDist = uv().distance(vec2(0.5, 0.48));
  const bgVert = mix(color('#0b0b10'), color('#16161d'), uv().y);
  backdropMat.colorNode = mix(bgVert, color('#1a1a22'), smoothstep(0.55, 0.0, bgDist).mul(0.6));
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // Composition group (scaled so the CTA reads as the hero subject)
  // ---------------------------------------------------------------
  const stage = new Group();
  stage.scale.setScalar(1.35);
  root.add(stage);

  // Mid-depth accent halo behind the button (depth plane #2)
  const haloGeo = new PlaneGeometry(3.6, 1.5);
  const haloMat = new MeshBasicNodeMaterial();
  haloMat.transparent = true;
  haloMat.depthWrite = false;
  haloMat.colorNode = color('#ff2a38');
  const haloD = uv().sub(vec2(0.5, 0.5)).mul(vec2(2.0, 2.4)).length();
  haloMat.opacityNode = smoothstep(1.0, 0.15, haloD).mul(0.1);
  const halo = new Mesh(haloGeo, haloMat);
  halo.position.set(0, 0, -0.5);
  stage.add(halo);
  disposables.push(haloGeo, haloMat);

  // ---------------------------------------------------------------
  // CTA BUTTON — extruded rounded rect, 2.6 x 0.68, r 0.08, chamfer
  // ---------------------------------------------------------------
  const W = 2.6, H = 0.68, R = 0.08;
  const hw = W / 2, hh = H / 2;
  const shape = new Shape();
  shape.moveTo(-hw + R, -hh);
  shape.lineTo(hw - R, -hh);
  shape.quadraticCurveTo(hw, -hh, hw, -hh + R);
  shape.lineTo(hw, hh - R);
  shape.quadraticCurveTo(hw, hh, hw - R, hh);
  shape.lineTo(-hw + R, hh);
  shape.quadraticCurveTo(-hw, hh, -hw, hh - R);
  shape.lineTo(-hw, -hh + R);
  shape.quadraticCurveTo(-hw, -hh, -hw + R, -hh);

  const buttonGeo = new ExtrudeGeometry(shape, {
    depth: 0.03,
    bevelEnabled: true,
    bevelThickness: 0.03,
    bevelSize: 0.03,
    bevelSegments: 1, // hard 45deg machined chamfer
    curveSegments: 10,
  });
  buttonGeo.center();

  const buttonMat = new MeshPhysicalNodeMaterial();
  buttonMat.roughness = 0.5;
  buttonMat.metalness = 0.35;
  buttonMat.clearcoat = 0.22;

  // Engineered vertical gradient: #ff4450 (0.0) -> #ff2a38 (0.55) -> #c1121f (1.0)
  const ny = clamp(positionLocal.y.div(H).add(0.5), 0.0, 1.0); // 0 bottom, 1 top
  const t = float(1.0).sub(ny); // 0 at top
  const c0 = color('#ff4450');
  const c1 = color('#ff2a38');
  const c2 = color('#c1121f');
  const g1 = clamp(t.div(0.55), 0.0, 1.0);
  const g2 = clamp(t.sub(0.55).div(0.45), 0.0, 1.0);
  let grad = mix(mix(c0, c1, g1), c2, g2);
  // Hard 0.01-unit seam line at 50% face height — zero blur
  const seam = float(1.0).sub(step(0.005, positionLocal.y.abs()));
  grad = mix(grad, color('#c1121f').mul(0.55), seam);
  buttonMat.colorNode = grad;

  // Perimeter emissive channel — 0.015 units wide, #ff2a38, driven uniform
  const edgeGlow = uniform(1.6);
  const edgeX = step(hw - 0.015, positionLocal.x.abs());
  const edgeY = step(hh - 0.015, positionLocal.y.abs());
  const edgeMask = max(edgeX, edgeY);
  buttonMat.emissiveNode = color('#ff2a38').mul(edgeMask).mul(edgeGlow);

  const ctaGroup = new Group();
  const button = new Mesh(buttonGeo, buttonMat);
  ctaGroup.add(button);
  stage.add(ctaGroup);
  disposables.push(buttonGeo, buttonMat);

  // ---------------------------------------------------------------
  // TEXT — spec copy verbatim via fontAtlas
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelItem = items.find((i) => i.role === 'cta-label') ?? items[0];
  const captionItem = items.find((i) => i.role === 'caption') ?? items[1];

  if (labelItem) {
    const fs = (labelItem.typography?.fontSize ?? 20) * 2;
    const label = ctx.fontAtlas.createText(String(labelItem.text), {
      fontSize: fs,
      color: '#16161d', // ink on the red gradient — 4.5:1+ local contrast
      align: 'center',
      letterSpacingPx: fs * 0.08,
    });
    label.position.set(0, 0, 0.08);
    ctaGroup.add(label);
  }

  if (captionItem) {
    const fs = (captionItem.typography?.fontSize ?? 9) * 2;
    const caption = ctx.fontAtlas.createText(String(captionItem.text), {
      fontSize: fs,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: fs * 0.12,
    });
    caption.position.set(0, -(hh + 0.25), 0.05);
    stage.add(caption);
  }

  // ---------------------------------------------------------------
  // CONTACT SHADOW — 0.08 below, 35% opacity, tightens on press
  // ---------------------------------------------------------------
  const shadowOp = uniform(0.35);
  const shadowGeo = new PlaneGeometry(3.2, 0.6);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  shadowMat.colorNode = vec3(0.0);
  const sd = uv().sub(vec2(0.5, 0.5)).mul(vec2(2.0, 2.6)).length();
  shadowMat.opacityNode = smoothstep(1.0, 0.15, sd).mul(shadowOp);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -(hh + 0.08), -0.08);
  stage.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------------------------------------------------------------
  // LIGHTING — accent rim from behind-left (scene provides key + ambient)
  // ---------------------------------------------------------------
  const rim = new DirectionalLight('#ff2a38', 1.0);
  rim.position.set(-2.2, 1.4, -2.0);
  root.add(rim);
  const fill = new DirectionalLight('#e8ecf2', 0.35);
  fill.position.set(1.6, -1.0, 2.4);
  root.add(fill);

  // ---------------------------------------------------------------
  // MOTION — weighted-settle mount 1.04 -> 1.0, 900ms power4.out
  // ---------------------------------------------------------------
  const settleTl = gsap.timeline();
  settleTl.fromTo(
    ctaGroup.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );
  timelines.push(settleTl);

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES (none in spec, applied if present)
  // ---------------------------------------------------------------
  for (const primitive of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[primitive.name];
    if (fn) primitiveHandles.push(fn(ctaGroup, primitive.params));
  }

  // ---------------------------------------------------------------
  // INTERACTION — hover lift + edge glow, press-down with shadow tighten
  // ---------------------------------------------------------------
  root.userData.handlers = {
    pointerenter: () => {
      gsap.to(ctaGroup.position, { z: 0.06, duration: 0.18, ease: 'power2.out' });
      gsap.to(edgeGlow, { value: 2.2, duration: 0.18, ease: 'power2.out' });
    },
    pointerleave: () => {
      gsap.to(ctaGroup.position, { z: 0, duration: 0.22, ease: 'power2.out' });
      gsap.to(edgeGlow, { value: 1.6, duration: 0.22, ease: 'power2.out' });
      gsap.to(ctaGroup.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'power2.out' });
      gsap.to(shadowOp, { value: 0.35, duration: 0.2, ease: 'power2.out' });
      gsap.to(shadow.scale, { x: 1, y: 1, duration: 0.2, ease: 'power2.out' });
    },
    pointerdown: () => {
      gsap.to(ctaGroup.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' });
      gsap.to(ctaGroup.position, { z: -0.015, duration: 0.12, ease: 'power2.out' });
      gsap.to(shadowOp, { value: 0.5, duration: 0.12, ease: 'power2.out' });
      gsap.to(shadow.scale, { x: 0.85, y: 0.85, duration: 0.12, ease: 'power2.out' });
    },
    pointerup: () => {
      gsap.to(ctaGroup.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power4.out' });
      gsap.to(ctaGroup.position, { z: 0.06, duration: 0.25, ease: 'power4.out' });
      gsap.to(shadowOp, { value: 0.35, duration: 0.25, ease: 'power2.out' });
      gsap.to(shadow.scale, { x: 1, y: 1, duration: 0.25, ease: 'power2.out' });
    },
    click: () => {
      ctx.emit('cta:activate', { id: config.id, label: labelItem ? String(labelItem.text) : 'BEGIN COMMISSION' });
    },
  };

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    gsap.killTweensOf(ctaGroup.position);
    gsap.killTweensOf(ctaGroup.scale);
    gsap.killTweensOf(shadow.scale);
    gsap.killTweensOf(edgeGlow);
    gsap.killTweensOf(shadowOp);
    for (const h of primitiveHandles) h.cleanup && h.cleanup();
    for (const d of disposables) d.dispose && d.dispose();
    root.remove(rim);
    root.remove(fill);
  };

  return root;
}
